mapper.update:
UPDATE t_derivation_rule SET name=#{name},
  derivation_type=#{derivationType},definition_json=CAST(#{definitionJson} AS JSON)
WHERE rule_code=#{ruleCode}

UPDATE t_derivation_rule SET name=#{name},derivation_type=#{derivationType},
  schedule_type=#{scheduleType},cron_expr=#{cronExpr},next_fire_at=#{nextFireAt},
  source_scope_json=CAST(#{sourceScopeJson} AS JSON),definition_json=CAST(#{definitionJson} AS JSON),
  algorithm_version=#{algorithmVersion},enabled=#{enabled}
WHERE rule_code=#{ruleCode}

UPDATE t_derivation_rule SET status=#{status},
  last_fire_at=#{lastFireAt},next_fire_at=#{nextFireAt},last_error=#{lastError}
WHERE rule_code=#{ruleCode}

UPDATE t_derivation_run SET status=#{status},scanned_count=#{scannedCount},
  candidate_count=#{candidateCount},stale_count=#{staleCount},error_message=#{errorMessage},
  finished_time=#{finishedTime} WHERE run_code=#{runCode}

mapper.select:
SELECT run_code runCode,knowledge_base_id knowledgeBaseId,
  rule_code ruleCode,trigger_type triggerType,status,scanned_count scannedCount,candidate_count candidateCount,
  stale_count staleCount,error_message errorMessage,started_time startedTime,finished_time finishedTime
FROM t_derivation_run WHERE (knowledge_base_id=#{kb} OR #{kb} IS NULL)
AND rule_code=#{ruleCode}
ORDER BY started_time DESC,id DESC LIMIT #{limit}
